'use strict';
const { parseDuration } = require('./duration.js');
const loadConfig = (raw = require('../config/app.json')) => ({ service: raw.service, cache: { ttlMs: parseDuration(raw.cache.ttl) * 1, maxEntries: raw.cache.maxEntries }, retry: { delayMs: parseDuration(raw.retry.delay), attempts: raw.retry.attempts } });
module.exports = { loadConfig };

